package com.jnapanam.sportszone.promotion.dto;import com.jnapanam.sportszone.payment.model.PaymentPurpose;import com.jnapanam.sportszone.promotion.model.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;public record PromotionResponse(UUID id,String code,String name,String description,DiscountType discountType,BigDecimal discountValue,Long maxDiscountPaise,long minOrderPaise,PaymentPurpose purpose,boolean automatic,boolean onlineOnly,Instant startsAt,Instant endsAt,Integer globalUsageLimit,int perUserLimit,int usageCount,boolean active){public static PromotionResponse from(Promotion p){return new PromotionResponse(p.getId(),p.getCode(),p.getName(),p.getDescription(),p.getDiscountType(),p.getDiscountValue(),p.getMaxDiscountPaise(),p.getMinOrderPaise(),p.getPurpose(),p.isAutomatic(),p.isOnlineOnly(),p.getStartsAt(),p.getEndsAt(),p.getGlobalUsageLimit(),p.getPerUserLimit(),p.getUsageCount(),p.isActive());}}
